START TRANSACTION;
INSERT INTO mes_production_conversion_archive(source_table,source_id,original_row,conversion_key,conversion_reason,archived_at) SELECT 'mes_quality_treatment',CAST(id AS CHAR),JSON_OBJECT('id',`id`,'request_hash',`request_hash`,'declaration_id',`declaration_id`,'declaration_revision',`declaration_revision`,'execution_id',`execution_id`,'routing_node_id',`routing_node_id`,'action_type',`action_type`,'attribution_type',`attribution_type`,'related_declaration_id',`related_declaration_id`,'basis',`basis`,'returned_qty',`returned_qty`,'operator_user_id',`operator_user_id`,'recorded_at',`recorded_at`,'reason',`reason`,'target_warehouse_id',`target_warehouse_id`,'stock_document_id',`stock_document_id`,'transfer_qty',`transfer_qty`),'internal-production-model-20261023','按用户指示退役动作转待入仓、旧完工恢复执行中、整组58条执行移除；原行留存审计',NOW(6) FROM `mes_quality_treatment` WHERE action_type IN ('ALLOCATE','START','RESULT','CANCEL_ALLOC','CANCEL_START','CORRECT_RESULT'); SELECT ROW_COUNT();
INSERT INTO mes_production_conversion_archive(source_table,source_id,original_row,conversion_key,conversion_reason,archived_at) SELECT 'mes_execution_completion',CAST(id AS CHAR),JSON_OBJECT('id',`id`,'execution_id',`execution_id`,'effective_qty',`effective_qty`,'released_qty',`released_qty`,'receipt_qty',`receipt_qty`,'accepted_qty',`accepted_qty`,'basis_hash',`basis_hash`,'request_hash',`request_hash`,'operator_user_id',`operator_user_id`,'recorded_at',`recorded_at`,'reason',`reason`),'internal-production-model-20261023','按用户指示退役动作转待入仓、旧完工恢复执行中、整组58条执行移除；原行留存审计',NOW(6) FROM `mes_execution_completion` WHERE execution_id IN (SELECT id FROM mes_production_execution WHERE status<>'FULLY_RECEIVED'); SELECT ROW_COUNT();
INSERT INTO mes_production_conversion_archive(source_table,source_id,original_row,conversion_key,conversion_reason,archived_at) SELECT 'mes_production_execution',CAST(id AS CHAR),JSON_OBJECT('id',`id`,'workorder_id',`workorder_id`,'product_id',`product_id`,'batch_no',`batch_no`,'routing_id',`routing_id`,'target_qty',`target_qty`,'status',`status`,'start_time',`start_time`,'end_time',`end_time`,'remark',`remark`,'create_by',`create_by`,'create_time',`create_time`,'update_by',`update_by`,'update_time',`update_time`),'internal-production-model-20261023','按用户指示退役动作转待入仓、旧完工恢复执行中、整组58条执行移除；原行留存审计',NOW(6) FROM `mes_production_execution` WHERE status IN ('COMPLETED','HISTORICAL'); SELECT ROW_COUNT();
INSERT INTO mes_production_conversion_archive(source_table,source_id,original_row,conversion_key,conversion_reason,archived_at) SELECT 'workorder',CAST(id AS CHAR),JSON_OBJECT('id',`id`,'code',`code`,'product_id',`product_id`,'planned_qty',`planned_qty`,'routing_id',`routing_id`,'status',`status`,'planned_start_at',`planned_start_at`,'planned_end_at',`planned_end_at`,'remark',`remark`,'revision',`revision`,'create_time',`create_time`,'update_time',`update_time`,'source',`source`),'internal-production-model-20261023','按用户指示退役动作转待入仓、旧完工恢复执行中、整组58条执行移除；原行留存审计',NOW(6) FROM `workorder` WHERE status='HISTORICAL' OR (status='COMPLETED' AND EXISTS(SELECT 1 FROM mes_production_execution e WHERE e.workorder_id=workorder.id AND e.status<>'FULLY_RECEIVED')); SELECT ROW_COUNT();
